begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is(private.canonical_reservation_phone('+840981152315'),'+84981152315','Country code with local trunk zero is normalized');
select is(private.canonical_reservation_phone('+84098115235'),null::text,'Missing Vietnamese digit rejected');
select is(private.canonical_reservation_phone('+3361234567'),null::text,'Missing French digit rejected');
select is(private.canonical_reservation_phone('+1650253000'),null::text,'Missing North American digit rejected');
select is(private.canonical_reservation_phone('+330612345678'),'+33612345678','French trunk prefix is normalized');
select is(private.canonical_reservation_phone('+39066982'),'+39066982','Significant Italian zero retained');
select ok(private.reservation_contact_is_official(null,'+840981152315'),'Reported official phone bypass blocked');
select throws_like($$select private.validate_guest_reservation_contact('+840981152315','visitor@gmail.com')$$,'%personal phone number%','Official phone fails before reservation');
select throws_like($$select private.validate_guest_reservation_contact('+84901234567',null)$$,'%email address is required%','Guest email mandatory');
select throws_like($$select private.validate_guest_reservation_contact('+84901234567','guest@vre-vietnam.com')$$,'%personal phone number%','Company email rejected');
select set_config('request.jwt.claims','{"role":"anon"}',true);
select set_config('request.jwt.claim.role','anon',true);
set local role anon;
select throws_like($$select public.create_guest_ticket_booking('individual',current_date+40,'16:00',30,2,1,'{}',0,0,'+840981152315',null,null,'visitor@gmail.com')$$,'%personal phone number%','Actual Ha Do guest RPC rejects reported bypass');
select throws_like($$select public.create_cafe_ticket_booking_request('individual',current_date+40,'16:00',30,2,1,'{}','+84098115235',null,null,'visitor@gmail.com')$$,'%valid phone number%','Actual Cafe guest RPC rejects missing digit');
select throws_like($$select public.create_guest_ticket_booking('individual',current_date+40,'16:00',30,2,1,'{}',0,0,'+84901234567',null,null)$$,'%email address is required%','Old API cannot omit guest email');
select throws_like($$select public.create_sim_racing_booking(current_date+40,'16:00','+840981152315',null,'visitor@gmail.com')$$,'%personal phone number%','Simulator guest cannot use official phone');
reset role;
select * from finish();
rollback;
